package com.dentalcrm.common;
import com.dentalcrm.doctor.*; import com.dentalcrm.patient.*; import com.dentalcrm.service.*; import com.dentalcrm.user.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Profile; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal;
@Component @Profile("dev") public class DevDataSeeder implements CommandLineRunner {private final UserRepository users;private final DoctorRepository doctors;private final PatientRepository patients;private final ClinicServiceRepository services;private final PasswordEncoder encoder;public DevDataSeeder(UserRepository u,DoctorRepository d,PatientRepository p,ClinicServiceRepository s,PasswordEncoder e){users=u;doctors=d;patients=p;services=s;encoder=e;}
 @Override @Transactional public void run(String... args){if(users.count()>0)return;User admin=user("admin","admin123","Clinic Administrator",Role.ADMIN);users.save(admin);User doctorUser=user("doctor","doctor123","Dr. Aizada Omurova",Role.DOCTOR);users.save(doctorUser);Doctor d=new Doctor();d.setUser(doctorUser);d.setSpecialization("General dentistry");d.setPhone("+996 555 000 101");doctors.save(d);Patient p=new Patient();p.setFullName("Development Patient");p.setPhone("+996 555 000 202");patients.save(p);ClinicService consultation=new ClinicService();consultation.setName("Consultation");consultation.setPrice(new BigDecimal("500.00"));consultation.setDurationMinutes(30);services.save(consultation);}
 private User user(String username,String password,String name,Role role){User u=new User();u.setUsername(username);u.setPasswordHash(encoder.encode(password));u.setFullName(name);u.setRole(role);u.setActive(true);return u;}
}
